cards.solution:
import java.time.*;

public class Main {
    public static void main(String[] args) {
        Instant bayar = Instant.parse("2026-10-30T15:20:00Z");
        Instant kirim = bayar.plusSeconds(2 * 60 * 60);
        System.out.println(kirim.atZone(ZoneId.of("Asia/Jakarta")).toLocalDateTime());
        System.out.println(Duration.between(bayar, kirim).getSeconds());
    }
}

